  ] as const) {
    it(`serializes a ${name} echoed body as JSON`, async () => {
      ctx.app.post("/echo", async (event) => echo(await readBody(event)));
      const res = await ctx.fetch("/echo", {
        method: "POST",
        body: JSON.stringify(forged),
        headers: { "content-type": "text/plain" },
